challenge.starter:
function isInstance(value, Ctor) {
  // 遍历原型链
}

challenge.solution:
function isInstance(value, Ctor) {
  if (value === null || !['object', 'function'].includes(typeof value)) return false;
  let p = Object.getPrototypeOf(value);
  while (p !== null) {
    if (p === Ctor.prototype) return true;
    p = Object.getPrototypeOf(p);
  }
  return false;
}

