function createPerson(initialAge) {
  const check = value => {
    if (!Number.isInteger(value) || value < 0) throw new RangeError("年龄必须为非负整数");
  };
  check(initialAge);
  return new Proxy({ age: initialAge }, {
    set(target, key, value, receiver) {
      if (key === "age") check(value);
      return Reflect.set(target, key, value, receiver);
    }
  });
}

