function observeWidth(win, render) {
  let active = true;
  const update = () => { if (active) render(win.innerWidth); };
  win.addEventListener("resize", update);
  update();
  return () => {
    if (!active) return;
    active = false;
    win.removeEventListener("resize", update);
  };
}

