function startCounter(button, onCount, timers = globalThis) {
  // 返回释放全部资源的函数
}

challenge.solution:
function startCounter(button, onCount, timers = globalThis) {
  let count = 0;
  let active = true;
  const click = () => { if (active) count++; };
  const tick = () => { if (active) onCount(count); };
  button.addEventListener("click", click);
  const id = timers.setInterval(tick, 1000);
  return () => {
    if (!active) return;
    active = false;
    button.removeEventListener("click", click);
    timers.clearInterval(id);
  };
}

