 type Product = Readonly<{ id: string; name: string; priceCents: number }>;
function parseProduct(value: unknown): Product | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const item = value as Record<string, unknown>;
  if (typeof item.id !== "string" || typeof item.name !== "string" ||
      typeof item.priceCents !== "number" || !Number.isSafeInteger(item.priceCents) || item.priceCents < 0) return null;
  return { id: item.id, name: item.name, priceCents: item.priceCents };
}
