import { useEffect, useState } from "react";
const KEY = "course-count-v1";
function readCount() {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || "null");
    if (saved?.version === 1 && Number.isSafeInteger(saved.count) && saved.count >= 0) return saved.count;
  } catch {}
  return 0;
}
export default function PersistentCounter() {
  const [count, setCount] = useState(readCount);
  const [error, setError] = useState("");
  useEffect(() => {
    try {
      localStorage.setItem(KEY, JSON.stringify({ version: 1, count }));
      setError("");
    } catch { setError("保存失败，本次计数可能无法在刷新后恢复。"); }
  }, [count]);
  return <section><p>{count}</p>
    <button disabled={count === Number.MAX_SAFE_INTEGER}
      onClick={() => setCount(value => value < Number.MAX_SAFE_INTEGER ? value + 1 : value)}>加一</button>
    {error && <p role="alert">{error}</p>}
  </section>;
}

